  "main": [
   "-- moon: print the phase of the Moon for a date.",
   "local phase = require(\"moon.phase\")",
   "local names = require(\"moon.names\")",
   "",
   "local date = arg[1] or os.date(\"!%Y-%m-%d\")",
   "local p = phase.of(date)",
   "",
   "print((\"%s  %s  %d%% lit\"):format(date, names.of(p.angle), p.lit))"
  ],
  "phase": [
   "-- Phase angle and illuminated fraction of the Moon (Meeus, ch. 48, low accuracy).",
   "local julian = require(\"moon.julian\")",
   "",
   "local M = {}",
   "",
   "local rad, sin, cos = math.rad, math.sin, math.cos",
   "",
   "function M.of(date)",
   "    local jd = julian.day(date)",
   "    local T = (jd - 2451545.0) / 36525",
   "",
   "    -- mean elongation, Sun's anomaly, Moon's anomaly (degrees)",
   "    local D  = 297.8501921 + 445267.1114034 * T",
   "    local Ms = 357.5291092 + 35999.0502909 * T",
   "    local Mm = 134.9633964 + 477198.8675055 * T",
   "",
   "    local i = 180 - D",
   "        - 6.289 * sin(rad(Mm))",
   "        + 2.100 * sin(rad(Ms))",
   "        - 1.274 * sin(rad(2 * D - Mm))",
   "        - 0.658 * sin(rad(2 * D))",
   "        - 0.214 * sin(rad(2 * Mm))",
   "        - 0.110 * sin(rad(D))",
   "",
   "    local lit = (1 + cos(rad(i))) / 2",
   "    return {",
   "        angle = (180 - i) % 360,              -- 0 new, 180 full",
   "        lit = math.floor(lit * 100 + 0.5),",
   "    }",
   "end",
   "",
   "return M"
  ],
  "julian": [
   "-- Julian day number of a calendar date at 00:00 UTC.",
   "local M = {}",
   "",
   "function M.day(date)",
   "    local y, m, d = date:match(\"^(%d+)-(%d+)-(%d+)$\")",
   "    assert(y, \"expected YYYY-MM-DD\")",
   "    y, m, d = tonumber(y), tonumber(m), tonumber(d)",
   "    if m <= 2 then",
   "        y, m = y - 1, m + 12",
   "    end",
   "    local a = math.floor(y / 100)",
   "    local b = 2 - a + math.floor(a / 4)",
   "    return math.floor(365.25 * (y + 4716))",
   "        + math.floor(30.6001 * (m + 1)) + d + b - 1524.5",
   "end",
   "",
   "return M"
  ],
  "names": [
   "-- Name of the phase for an elongation angle (0 new, 180 full).",
   "local M = {}",
   "",
   "local list = {",
   "    \"new moon\", \"waxing crescent\", \"first quarter\", \"waxing gibbous\",",
   "    \"full moon\", \"waning gibbous\", \"last quarter\", \"waning crescent\",",
   "}",
   "",
   "function M.of(angle)",
   "    return list[math.floor((angle + 22.5) / 45) % 8 + 1]",
   "end",
   "",
   "return M"
  ]
